package cn.zj.zjmarket.infrastructure.dao;

import cn.zj.zjmarket.domain.product.model.valobj.QuarantinedMessage;
import cn.zj.zjmarket.domain.product.model.valobj.SyncBadMessage;
import cn.zj.zjmarket.domain.product.model.valobj.SyncWork;
import cn.zj.zjmarket.infrastructure.dao.po.SyncInboxRow;
import java.util.List;
import org.apache.ibatis.annotations.*;
public interface IProductSyncDao {
 String COLS="event_id AS eventId,goods_id AS goodsId,product_version AS version,snapshot_sale_status AS saleStatus,body,body_hash AS bodyHash,delivery_state AS deliveryState,send_attempts AS sendAttempts,send_failures AS sendFailures,query_attempts AS queryAttempts,lease_token AS leaseToken,processing_state AS processingState,paused";
 @Select("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)") long now();
 @Select("<script>SELECT "+COLS+" FROM b_product_outbox WHERE event_id=#{id}<if test='lock'> FOR UPDATE</if></script>") SyncWork event(@Param("id")String id,@Param("lock")boolean lock);
 @Select("<script>SELECT "+COLS+" FROM b_product_outbox WHERE processing_state='WAITING' AND paused=FALSE AND lease_until_ms &lt;= CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)<if test='id != null'> AND event_id=#{id}</if><choose><when test='kind == &quot;SEND&quot;'> AND delivery_state='PENDING' AND next_send_ms &lt;= CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)</when><otherwise> AND (delivery_state='PUBLISHED' OR send_attempts>0) AND next_query_ms &lt;= CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)</otherwise></choose> ORDER BY created_at_ms,event_id LIMIT 1 FOR UPDATE SKIP LOCKED</script>") SyncWork candidate(@Param("kind")String kind,@Param("id")String id);
 @Update("UPDATE b_product_outbox SET lease_token=#{token},lease_until_ms=#{until},send_attempts=send_attempts+#{send},query_attempts=query_attempts+#{query} WHERE event_id=#{id}") int claim(@Param("id")String id,@Param("token")String token,@Param("until")long until,@Param("send")int send,@Param("query")int query);
 @Update("UPDATE b_product_outbox SET delivery_state='PUBLISHED',send_failures=0,last_error=NULL,next_query_ms=#{next},lease_token=NULL,lease_until_ms=0 WHERE event_id=#{id} AND lease_token=#{token} AND lease_until_ms>#{now} AND processing_state='WAITING' AND paused=FALSE") int sent(@Param("id")String id,@Param("token")String token,@Param("now")long now,@Param("next")long next);
 @Update("UPDATE b_product_outbox SET send_failures=send_failures+#{send},last_error=#{code},processing_state=#{state},paused=#{paused},next_send_ms=#{nextSend},next_query_ms=#{nextQuery},lease_token=NULL,lease_until_ms=0 WHERE event_id=#{id} AND lease_token=#{token} AND lease_until_ms>#{now} AND processing_state='WAITING' AND paused=FALSE") int failed(@Param("id")String id,@Param("token")String token,@Param("now")long now,@Param("send")int send,@Param("code")String code,@Param("state")String state,@Param("paused")boolean paused,@Param("nextSend")long nextSend,@Param("nextQuery")long nextQuery);
 @Update("UPDATE b_product_outbox SET next_query_ms=#{next},last_error=#{status},lease_token=NULL,lease_until_ms=0 WHERE event_id=#{id} AND lease_token=#{token} AND lease_until_ms>#{now} AND processing_state='WAITING'") int checked(@Param("id")String id,@Param("token")String token,@Param("now")long now,@Param("next")long next,@Param("status")String status);


 @Select("SELECT body_hash AS bodyHash,original_event_id AS originalEventId FROM b_sync_inbox WHERE consumer=#{consumer} AND producer=#{producer} AND event_id=#{id} FOR UPDATE") SyncInboxRow inbox(@Param("consumer")String consumer,@Param("producer")String producer,@Param("id")String id);
 @Insert("INSERT INTO b_sync_inbox(consumer,producer,event_id,body_hash,original_event_id,processing_outcome,result_body,processed_at_ms) VALUES(#{consumer},#{producer},#{id},#{hash},#{original},#{outcome},#{body},#{now})") int inboxInsert(@Param("consumer")String consumer,@Param("producer")String producer,@Param("id")String id,@Param("hash")String hash,@Param("original")String original,@Param("outcome")String outcome,@Param("body")String body,@Param("now")long now);
 @Select("SELECT last_error FROM b_product_outbox WHERE event_id=#{id}") String eventError(String id);
 @Select("SELECT result_hash FROM b_product_outbox WHERE event_id=#{id}") String resultHash(String id);
 @Update("UPDATE b_product_outbox SET processing_state=#{state},result_body=COALESCE(result_body,#{body}),result_hash=COALESCE(result_hash,#{hash}),outcome=COALESCE(outcome,#{outcome}),result_code=COALESCE(result_code,#{code}),last_error=#{error},lease_token=NULL,lease_until_ms=0 WHERE event_id=#{id}") int result(@Param("id")String id,@Param("state")String state,@Param("hash")String hash,@Param("outcome")String outcome,@Param("code")String code,@Param("error")String error,@Param("body")String body);
 @Update("UPDATE b_product_sync SET state=#{state},last_error=#{error},checked_at=#{time} WHERE goods_id=#{goods} AND target_event_id=#{id} AND target_version=#{version}") int progress(@Param("goods")String goods,@Param("id")String id,@Param("version")long version,@Param("state")String state,@Param("error")String error,@Param("time")String time);
 @Update("UPDATE b_product_sync SET confirmed_version=GREATEST(COALESCE(confirmed_version,0),#{version}) WHERE goods_id=#{goods} AND target_version>=#{version}") int confirmed(@Param("goods")String goods,@Param("version")long version);
 @Update("UPDATE b_product_outbox SET paused=#{pause},delivery_state=CASE WHEN #{pause} THEN delivery_state ELSE 'PENDING' END,processing_state='WAITING',last_error=#{error},next_send_ms=#{now},next_query_ms=#{now},lease_token=NULL,lease_until_ms=0 WHERE event_id=#{id}") int control(@Param("id")String id,@Param("pause")boolean pause,@Param("error")String error,@Param("now")long now);
 @Insert("INSERT INTO b_sync_audit(audit_id,goods_id,event_id,operator_id,action,occurred_at_ms) VALUES(#{audit},#{goods},#{id},#{operator},#{action},#{now})") int audit(@Param("audit")String audit,@Param("goods")String goods,@Param("id")String id,@Param("operator")String operator,@Param("action")String action,@Param("now")long now);
 @Insert("INSERT IGNORE INTO b_sync_quarantine(quarantine_id,dedup_hash,body_hash,topic,tag,key_id,signature,body,original_size,reason,stored_at_ms) VALUES(#{id},#{dedup},#{hash},#{topic},#{tag},#{key},#{signature},#{body},#{size},#{reason},#{now})") int quarantine(@Param("id")String id,@Param("dedup")String dedup,@Param("hash")String hash,@Param("topic")String topic,@Param("tag")String tag,@Param("key")String key,@Param("signature")String signature,@Param("body")byte[] body,@Param("size")int size,@Param("reason")String reason,@Param("now")long now);
 @Select("SELECT quarantine_id FROM b_sync_quarantine WHERE dedup_hash=#{hash}") String quarantineId(String hash);
 @Select("SELECT quarantine_id AS quarantineId,body_hash AS bodyHash,reason,original_size AS originalSize,stored_at_ms AS storedAt,CASE WHEN replayed_at_ms IS NULL THEN 'QUARANTINED' ELSE 'REPLAYED' END AS state FROM b_sync_quarantine ORDER BY stored_at_ms DESC,quarantine_id DESC LIMIT #{size} OFFSET #{offset}") List<QuarantinedMessage> quarantined(@Param("size")int size,@Param("offset")long offset);
 @Select("SELECT COUNT(*) FROM b_sync_quarantine") long quarantineCount();
 @Select("SELECT topic,tag,key_id AS keyId,signature,body,reason FROM b_sync_quarantine WHERE quarantine_id=#{id} AND original_size=OCTET_LENGTH(body)") SyncBadMessage quarantinedBody(String id);
 @Update("UPDATE b_sync_quarantine SET replayed_at_ms=#{now} WHERE quarantine_id=#{id}") int replayed(@Param("id")String id,@Param("now")long now);
}
